<?php
namespace Modules\BankingMicrofinance\Http\Controllers;use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;
class AdvancedReportController extends Controller{public function aging(Request $request){$rows=DB::table('bkg_mfi_installments')->select('loan_id',DB::raw('SUM(CASE WHEN due_date < CURDATE() THEN amount - COALESCE(paid_amount,0) ELSE 0 END) overdue_amount'),DB::raw('COUNT(*) installment_count'))->groupBy('loan_id')->paginate(50);return view('bankingmicrofinance::reports.aging',compact('rows'));}public function portfolio(Request $request){$rows=DB::table('bkg_mfi_loans')->select('status',DB::raw('COUNT(*) loans'),DB::raw('SUM(principal_amount) principal'),DB::raw('SUM(balance_amount) balance'))->groupBy('status')->get();return view('bankingmicrofinance::reports.portfolio',compact('rows'));}public function collectionEfficiency(Request $request){$rows=DB::table('bkg_mfi_collections')->select(DB::raw('DATE(collection_date) date'),DB::raw('SUM(amount) collected'))->groupBy(DB::raw('DATE(collection_date)'))->orderByDesc('date')->paginate(31);return view('bankingmicrofinance::reports.collection_efficiency',compact('rows'));}}
